class PurePyADAA(ADAA):
    """Pure Python data layer"""

    _IDENTIFIER = "PUREPYTHON"

    @classmethod
    def _empty(cls, size):
        real = [0.0 for _ in range(size)]
        imag = [0.0 for _ in range(size)]
        return real, imag


class NumpyADAA(ADAA):
    """Numpy based data layer"""

    _IDENTIFIER = "NUMPY"

    @classmethod
    def _empty(cls, size):
        real = np.zeros(size)
        imag = np.zeros(size)
        return real, imag


class FortranADAA(ADAA):
    """FORTRAN based data layer (implemented via NumPy)"""

    _IDENTIFIER = "FORTRAN"

    @classmethod
    def _empty(cls, size):
        real = np.zeros(size)
        imag = np.zeros(size)
        return real, imag


class CupyADAA(ADAA):
    """Cupy based data layer"""

    _IDENTIFIER = "CUPY"

    @classmethod
    def _empty(cls, size):
        real = cp.zeros(size)
        imag = cp.zeros(size)
        return real, imag


class OpenClADAA(ADAA):
    """Cupy based data layer"""

    _IDENTIFIER = "OPENCL"

    _CL_CTX = cl.create_some_context()
    _CL_QUEUE = cl.CommandQueue(_CL_CTX)

    _CL_MF = cl.mem_flags

    @classmethod
    def _empty(cls, size):
        real = cl.Buffer(
            cls._CL_CTX,
            cls._CL_MF.READ_ONLY | cls._CL_MF.COPY_HOST_PTR,
            hostbuf=np.zeros(size),
        )
        imag = cl.Buffer(
            cls._CL_CTX,
            cls._CL_MF.READ_ONLY | cls._CL_MF.COPY_HOST_PTR,
            hostbuf=np.zeros(size),
        )
        return real, imag


